(function(){"use strict";
  var logout=document.getElementById("logout");
  if(logout)logout.addEventListener("click",function(){fetch("https://api.hongzhtaichina.com/api/ui/logout",{method:"POST",credentials:"include"}).finally(function(){sessionStorage.removeItem("hzt_tbot_authenticated");location.replace("./tbot-login.html")})});
  var status=document.getElementById("api-status");
  if(status){fetch("https://api.hongzhtaichina.com/health",{mode:"cors",cache:"no-store"}).then(function(r){if(!r.ok)throw Error();status.textContent="ONLINE"}).catch(function(){status.textContent="PROTECTED"})}
  var titles={"workbench":["Workbench","Driver command surface · manual controls and live link state."],"lead-discovery":["Lead Discovery","Lead discovery and Hbot control center · manual only."],"clients":["Clients","Customer management, chat history and media context."],"whitelist":["Whitelist & Depts","Identity, departments and approved-number policies."],"keypool":["API Keypool Hot","Provider health and mirror hot-standby state."],"plugins":["OpenClaw Plugins","Mounted skills and communications equipment."],"runtime-logs":["Runtime Logs","Sanitized operational evidence and lifecycle events."]};
  var links=document.querySelectorAll(".side-link[data-module]"),panels=document.querySelectorAll(".module-panel[data-panel]"),title=document.getElementById("module-title"),subtitle=document.getElementById("module-subtitle"),feedback=document.getElementById("module-feedback");
  function select(name){var info=titles[name]||titles.workbench;name=titles[name]?name:"workbench";links.forEach(function(a){a.classList.toggle("active",a.getAttribute("data-module")===name)});panels.forEach(function(p){p.classList.toggle("active",p.getAttribute("data-panel")===name)});if(title)title.textContent=info[0];if(subtitle)subtitle.textContent=info[1];if(history.replaceState)history.replaceState(null,"","#"+name)}
  var actionText={"hbot-start":"Start is a local GUI-owned Hbot action; this public page cannot start a process.","hbot-stop":"Stop is a local GUI-owned Hbot action; this public page cannot stop a process.","hbot-refresh":"Refresh requires the authenticated local data API.","hbot-list":"List requires the authenticated local data API.","hbot-stats":"Stats requires the authenticated local data API.","hbot-archive":"Archive is a gated local operation; no public mutation was sent.","hbot-status":"Status requires the authenticated local runtime probe.","clients-refresh":"Refreshing the authenticated Clients projection…","clients-open":"Focusing the selected client conversation."};
  document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest(".side-link[data-module]");if(a){e.preventDefault();select(a.getAttribute("data-module"));return}var b=e.target.closest&&e.target.closest(".module-action[data-action]");if(b&&feedback){e.preventDefault();feedback.textContent=actionText[b.getAttribute("data-action")]||"This control requires the authenticated local runtime.";feedback.classList.add("is-error")}});
  window.addEventListener("hashchange",function(){select(location.hash.slice(1))});
  var initial=location.hash.slice(1);select(titles[initial]?initial:"workbench");
})();
